import json, os, subprocess, sys
from pathlib import Path
analysis_path = Path('/root/infusion_batch_analysis.json')
summary_path = Path('/root/infusion_batch_summary.md')
analysis = json.loads(analysis_path.read_text())
errors = []
expected_assumptions = {
  'deliveries_per_year_7_day': 52,
  'deliveries_per_year_14_day': 26,
  'days_per_delivery_7_day': 7,
  'days_per_delivery_14_day': 14,
  'switch_threshold_usd': 15000,
  'patient_override_rule': 'highest approved revision per therapy_code'
}
if analysis.get('assumptions') != expected_assumptions:
    errors.append(f"assumptions mismatch: {analysis.get('assumptions')}")
therapy_codes = [t.get('therapy_code') for t in analysis.get('therapies', [])]
if therapy_codes != sorted(therapy_codes):
    errors.append(f"therapies not sorted: {therapy_codes}")
required_therapy_keys = {
    'therapy_code','therapy_name','active_patients','patient_override_revision','patient_override_status',
    'patient_count_column','bag_size_ml','bag_supply_cost_usd','payment_per_delivery_per_patient_usd',
    'drug_cost_per_1000_mg_usd','dose_mg_per_day','annual_drug_cost_7_day_usd',
    'annual_supply_cost_7_day_usd','annual_revenue_7_day_usd','annual_margin_7_day_usd',
    'annual_drug_cost_14_day_usd','annual_supply_cost_14_day_usd','annual_revenue_14_day_usd',
    'annual_margin_14_day_usd','annual_margin_difference_14_minus_7_usd'
}
currency_keys = [
    'bag_supply_cost_usd','payment_per_delivery_per_patient_usd','drug_cost_per_1000_mg_usd',
    'annual_drug_cost_7_day_usd','annual_supply_cost_7_day_usd','annual_revenue_7_day_usd',
    'annual_margin_7_day_usd','annual_drug_cost_14_day_usd','annual_supply_cost_14_day_usd',
    'annual_revenue_14_day_usd','annual_margin_14_day_usd','annual_margin_difference_14_minus_7_usd'
]
for t in analysis.get('therapies', []):
    missing = required_therapy_keys - set(t)
    if missing:
        errors.append(f"{t.get('therapy_code')} missing keys {sorted(missing)}")
    for key in currency_keys:
        if key in t and round(t[key], 2) != t[key]:
            errors.append(f"{t.get('therapy_code')} {key} not rounded: {t[key]}")
for key in ['total_annual_margin_7_day_usd','total_annual_margin_14_day_usd','total_annual_margin_difference_14_minus_7_usd','absolute_total_margin_difference_usd']:
    value = analysis.get('totals', {}).get(key)
    if value is None or round(value, 2) != value:
        errors.append(f"total {key} missing/not rounded: {value}")
if analysis.get('recommendation', {}).get('decision') not in {'move_to_14_day', 'keep_7_day'}:
    errors.append('bad decision')
lines = [line for line in summary_path.read_text().splitlines() if line.strip()]
if not (4 <= len(lines) <= 8):
    errors.append(f"summary non-empty line count {len(lines)}")
summary = '\n'.join(lines)
for needle in ['Total 7-day margin (USD)', 'Total 14-day margin (USD)', 'Absolute difference (USD)', analysis['recommendation']['decision']]:
    if needle not in summary:
        errors.append(f"summary missing {needle}")
if Path('/tests/test_outputs.py').exists():
    result = subprocess.run([sys.executable, '-m', 'pytest', '/tests', '-v'], cwd='/root', text=True, capture_output=True)
    print(result.stdout)
    print(result.stderr)
    if result.returncode != 0:
        errors.append(f"pytest failed with exit {result.returncode}")
else:
    print('/tests/test_outputs.py not present; skipped pytest.')
if errors:
    print('VALIDATION FAILED')
    print('\n'.join(errors))
    raise SystemExit(1)
print('VALIDATION PASSED')
print(f"therapies={therapy_codes}")
print(f"summary_non_empty_lines={len(lines)}")
